import sys

_set_int_max_str_digits = getattr(sys, "set_int_max_str_digits", None)
if _set_int_max_str_digits is not None:
    try:
        _set_int_max_str_digits(0)
    except ValueError:
        pass


class _Frame:
    __slots__ = ("kind", "container", "expect", "key")

    def __init__(self, kind, container, expect, key):
        self.kind = kind
        self.container = container
        self.expect = expect
        self.key = key


class _Parser:
    __slots__ = ("text", "pos", "n", "stack", "result", "done")

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.n = len(text)
        self.stack = []
        self.result = None
        self.done = False

    def parse(self):
        self._skip_ws()
        if self.pos >= self.n:
            raise ValueError

        self._parse_value_start()

        while self.stack:
            self._process_top_frame()

        self._skip_ws()
        if self.pos != self.n:
            raise ValueError

        return self.result

    def _skip_ws(self):
        text = self.text
        n = self.n
        pos = self.pos

        while pos < n:
            c = text[pos]
            if c == " " or c == "\t" or c == "\n" or c == "\r":
                pos += 1
            else:
                break

        self.pos = pos

    def _parse_value_start(self):
        self._skip_ws()

        if self.pos >= self.n:
            raise ValueError

        c = self.text[self.pos]

        if c == "{":
            self.pos += 1
            self.stack.append(_Frame(1, {}, 0, None))
            return

        if c == "[":
            self.pos += 1
            self.stack.append(_Frame(0, [], 0, None))
            return

        if c == '"':
            value = self._parse_string()
            self._complete_value(value)
            return

        if c == "-" or "0" <= c <= "9":
            value = self._parse_number()
            self._complete_value(value)
            return

        text = self.text
        pos = self.pos

        if c == "t":
            if not text.startswith("true", pos):
                raise ValueError
            self.pos = pos + 4
            self._complete_value(True)
            return

        if c == "f":
            if not text.startswith("false", pos):
                raise ValueError
            self.pos = pos + 5
            self._complete_value(False)
            return

        if c == "n":
            if not text.startswith("null", pos):
                raise ValueError
            self.pos = pos + 4
            self._complete_value(None)
            return

        raise ValueError

    def _process_top_frame(self):
        frame = self.stack[-1]

        if frame.kind == 0:  # array
            expect = frame.expect

            if expect == 0:  # after '[': value or ']'
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                c = self.text[self.pos]
                if c == "]":
                    self.pos += 1
                    self._close_frame(frame)
                else:
                    self._parse_value_start()

            elif expect == 1:  # after array element: ',' or ']'
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                c = self.text[self.pos]
                if c == "]":
                    self.pos += 1
                    self._close_frame(frame)
                elif c == ",":
                    self.pos += 1
                    frame.expect = 2
                else:
                    raise ValueError

            elif expect == 2:  # after array comma: value only
                if self._has_close_at_current():
                    raise ValueError
                self._parse_value_start()

            else:
                raise ValueError

        else:  # object
            expect = frame.expect

            if expect == 0:  # after '{': key or '}'
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                c = self.text[self.pos]
                if c == "}":
                    self.pos += 1
                    self._close_frame(frame)
                elif c == '"':
                    key = self._parse_string()
                    frame.key = key
                    frame.expect = 1
                else:
                    raise ValueError

            elif expect == 1:  # after key: ':'
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                if self.text[self.pos] != ":":
                    raise ValueError

                self.pos += 1
                frame.expect = 2

            elif expect == 2:  # after ':' : value
                self._parse_value_start()

            elif expect == 3:  # after object value: ',' or '}'
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                c = self.text[self.pos]
                if c == "}":
                    self.pos += 1
                    self._close_frame(frame)
                elif c == ",":
                    self.pos += 1
                    frame.expect = 4
                else:
                    raise ValueError

            elif expect == 4:  # after object comma: key only
                self._skip_ws()
                if self.pos >= self.n:
                    raise ValueError

                c = self.text[self.pos]
                if c == '"':
                    key = self._parse_string()
                    frame.key = key
                    frame.expect = 1
                elif c == "}":
                    raise ValueError
                else:
                    raise ValueError

            else:
                raise ValueError

    def _has_close_at_current(self):
        self._skip_ws()
        return self.pos < self.n and self.text[self.pos] == "]"

    def _close_frame(self, frame):
        self.stack.pop()
        self._complete_value(frame.container)

    def _complete_value(self, value):
        if not self.stack:
            self.result = value
            self.done = True
            return

        frame = self.stack[-1]

        if frame.kind == 0:  # array
            if frame.expect != 0 and frame.expect != 2:
                raise ValueError
            frame.container.append(value)
            frame.expect = 1

        else:  # object
            if frame.expect != 2:
                raise ValueError

            key = frame.key
            if key is None or key in frame.container:
                raise ValueError

            frame.container[key] = value
            frame.key = None
            frame.expect = 3

    def _parse_number(self):
        text = self.text
        n = self.n
        start = self.pos
        pos = start

        if pos >= n:
            raise ValueError

        if text[pos] == "-":
            pos += 1

        if pos >= n:
            raise ValueError

        c = text[pos]
        if not ("0" <= c <= "9"):
            raise ValueError

        if c == "0":
            pos += 1
        else:
            pos += 1
            while pos < n:
                c = text[pos]
                if "0" <= c <= "9":
                    pos += 1
                else:
                    break

        has_fraction = False
        if pos < n and text[pos] == ".":
            has_fraction = True
            pos += 1

            if pos >= n:
                raise ValueError

            c = text[pos]
            if not ("0" <= c <= "9"):
                raise ValueError

            while pos < n:
                c = text[pos]
                if "0" <= c <= "9":
                    pos += 1
                else:
                    break

        has_exponent = False
        if pos < n:
            c = text[pos]
            if c == "e" or c == "E":
                has_exponent = True
                pos += 1

                if pos < n:
                    c = text[pos]
                    if c == "+" or c == "-":
                        pos += 1

                if pos >= n:
                    raise ValueError

                c = text[pos]
                if not ("0" <= c <= "9"):
                    raise ValueError

                while pos < n:
                    c = text[pos]
                    if "0" <= c <= "9":
                        pos += 1
                    else:
                        break

        self.pos = pos
        number_text = text[start:pos]

        if has_fraction or has_exponent:
            return float(number_text)

        return int(number_text)

    def _parse_string(self):
        text = self.text
        n = self.n
        pos = self.pos

        if pos >= n or text[pos] != '"':
            raise ValueError

        pos += 1
        parts = []
        start = pos

        while pos < n:
            c = text[pos]

            if c == '"':
                if start < pos:
                    parts.append(text[start:pos])
                self.pos = pos + 1
                return "".join(parts)

            if c == "\\":
                if start < pos:
                    parts.append(text[start:pos])

                pos += 1
                if pos >= n:
                    raise ValueError

                c = text[pos]

                if c == '"':
                    parts.append('"')
                    pos += 1
                    start = pos

                elif c == "\\":
                    parts.append("\\")
                    pos += 1
                    start = pos

                elif c == "/":
                    parts.append("/")
                    pos += 1
                    start = pos

                elif c == "b":
                    parts.append("\b")
                    pos += 1
                    start = pos

                elif c == "f":
                    parts.append("\f")
                    pos += 1
                    start = pos

                elif c == "n":
                    parts.append("\n")
                    pos += 1
                    start = pos

                elif c == "r":
                    parts.append("\r")
                    pos += 1
                    start = pos

                elif c == "t":
                    parts.append("\t")
                    pos += 1
                    start = pos

                elif c == "u":
                    pos += 1
                    code, pos = self._parse_hex4(pos)

                    if 0xD800 <= code <= 0xDBFF:
                        if pos >= n or text[pos] != "\\":
                            raise ValueError

                        pos += 1
                        if pos >= n or text[pos] != "u":
                            raise ValueError

                        pos += 1
                        low, pos = self._parse_hex4(pos)

                        if not (0xDC00 <= low <= 0xDFFF):
                            raise ValueError

                        code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)

                    elif 0xDC00 <= code <= 0xDFFF:
                        raise ValueError

                    parts.append(chr(code))
                    start = pos

                else:
                    raise ValueError

                continue

            if c <= "\u001f":
                raise ValueError

            if "\ud800" <= c <= "\udfff":
                raise ValueError

            pos += 1

        raise ValueError

    def _parse_hex4(self, pos):
        text = self.text
        n = self.n

        if pos + 4 > n:
            raise ValueError

        value = 0

        for _ in range(4):
            c = text[pos]
            pos += 1

            if "0" <= c <= "9":
                value = (value << 4) | (ord(c) - 48)
            elif "a" <= c <= "f":
                value = (value << 4) | (ord(c) - 97)
            elif "A" <= c <= "F":
                value = (value << 4) | (ord(c) - 55)
            else:
                raise ValueError

        return value, pos


def parse_json(text: str) -> object:
    parser = _Parser(text)
    return parser.parse()
